package com.schoolmanagement.report;
import com.schoolmanagement.attendance.*;import com.schoolmanagement.security.UserContext;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.time.ZoneId;import java.util.*;import java.util.stream.Collectors;
@RestController @RequestMapping("/api/v1/reports") public class ReportController {private final AttendanceEventRepository events;private final UserContext ctx;public ReportController(AttendanceEventRepository e,UserContext c){events=e;ctx=c;}@GetMapping("/attendance-summary") public Map<String,Object> summary(@RequestParam(required=false) LocalDate date){LocalDate d=date==null?LocalDate.now(ZoneId.of("Africa/Accra")):date;var list=events.findAllBySchoolIdOrderByEventTimeDesc(ctx.schoolId()).stream().filter(e->e.getEventTime().atZone(ZoneId.of("Africa/Accra")).toLocalDate().equals(d)).toList();long arrivals=list.stream().filter(e->e.getEventType()==EventType.ARRIVAL).count();long departures=list.stream().filter(e->e.getEventType()==EventType.DEPARTURE).count();return Map.of("date",d.toString(),"arrivals",arrivals,"departures",departures,"events",list);}}
